('source.india.mahabharata.adiparvan.gretil','Mahābhārata, Ādiparvan (critical-edition e-text)','महाभारत — आदिपर्वन्','SCHOLARLY_DIGITAL_TEXT',2,'GRETIL / University of Goettingen','Critical edition by V. S. Sukthankar et al., Bhandarkar Oriental Research Institute (Ādiparvan, 1933); e-text entered by Muneo Tokunaga et al. and revised by John Smith','lang.san','1933','2026-10-02','https://gretil.sub.uni-goettingen.de/gretil/1_sanskr/2_epic/mbh/mbh_01_u.htm',NULL,'MBh_CE_1.15-1.17','Reference use; source-file rights apply','Constituted text of the BORI critical edition in an academic digital transcription',NULL,'Academic digital transcription of a philological reconstruction',0,'Reference and locator use only; follow GRETIL source-file terms; no bulk reproduction of the e-text or of modern translations.',0,'Sanskrit transcription (IAST)','URL_SYNTAX_VALID','The constituted critical text is one scholarly witness. Manuscript-apparatus, appendix, regional and performative versions remain separate and are queued; GRETIL file title matched through public search-index metadata on 2026-10-02.'),
('source.india.bhagavatapurana.gretil','Bhāgavatapurāṇa (GRETIL e-text)','भागवतपुराण','SCHOLARLY_DIGITAL_TEXT',2,'GRETIL / University of Goettingen','Received Purāṇic text; GRETIL TEI transformation','lang.san',NULL,'2026-10-02','https://gretil.sub.uni-goettingen.de/gretil/corpustei/transformations/html/sa_bhAgavatapurANa.htm',NULL,'BhP_8.5-8.9','Reference use; source-file rights apply','Academic digital transcription of a Purāṇa that remains scripture in living devotional traditions','Hindu devotional traditions, notably Vaiṣṇava','Academic digital transcription',1,'Public scripture context: locators and independent descriptive summaries only; no adjudication of theology or ritual practice and no bulk reproduction of modern devotional translations.',0,'Sanskrit transcription','URL_SYNTAX_VALID','Skandha 8, adhyāyas 5–9 supply the churning sequence used here; HTML transformation matched through public search-index metadata on 2026-10-02.');

INSERT OR IGNORE INTO entities(
    id,canonical_name,name_zh,original_name,transliteration,primary_type,
    primary_civilization_id,historical_period,description,research_status,
