('deity.chinese.gonggong','Witness-scoped mythic figure','Received early Chinese narrative layers',NULL,'[]','[]','["神祇、氏族首领或争帝者的身份侧重因来源而异，不统一判定"]','{}','[]',NULL,NULL),
('deity.hindu.kurma','Tortoise form of Viṣṇu (Bhāgavata witness)','Vaiṣṇava Purāṇic narrative',NULL,'[]','["supports Mount Mandara on his back"]','["不与《摩诃婆罗多》精校本中的龟王阿库帕拉自动等同"]','{"form":"giant tortoise"}','[]',NULL,NULL),
('deity.hindu.mohini','Enchanting female form of Viṣṇu (Bhāgavata witness)','Vaiṣṇava Purāṇic narrative',NULL,'[]','["distributes the amṛta while deluding the asuras"]','["《摩诃婆罗多》见证只描述迷惑的女身，不据此补写专名"]','{"form":"enchanting woman"}','[]',NULL,NULL),
('deity.hindu.dhanvantari','Divine bearer of the amṛta','Epic and Purāṇic narrative',NULL,'[]','["emerges from the churned ocean with the amṛta"]','[]','{}','["vessel of amṛta"]',NULL,NULL);

INSERT OR IGNORE INTO creature_profiles(
    entity_id,creature_class,appearance_json,abilities_json,weaknesses_json,
    habitat_summary,origin_summary,fate_summary
) VALUES
('creature.chinese.ao_turtle','GREAT_TURTLE','{}','[]','[]',NULL,'Named in the Huainanzi Lan Ming and Liezi Tang Wen Nüwa passages.','Its legs are cut off and used to set up the four poles in both witnesses.'),
('dragon.chinese.black_dragon_jizhou','DRAGON','{"color":"black"}','[]','[]',NULL,'Named only in the Huainanzi Lan Ming Nüwa passage.','Killed by Nüwa to relieve Jizhou in that witness.'),
('creature.hindu.vasuki','NAGA_KING','{"form":"serpent"}','[]','[]',NULL,'Nāga king in the epic and Purāṇic churning witnesses.','Serves as the churning rope in both registered witnesses.'),
('creature.hindu.akupara','TORTOISE_KING','{"form":"tortoise"}','["bears Mount Mandara"]','[]',NULL,'Named as king of tortoises in the Mahābhārata critical-edition churning witness.','Supports the mountain during the churning in that witness.'),
('demon.hindu.rahu','DANAVA','{}','[]','[]',NULL,'Dānava in the epic and Purāṇic churning witnesses.','Beheaded with Viṣṇu''s discus after drinking the amṛta in disguise; later astral identities are not modeled here.');

INSERT OR IGNORE INTO artifact_profiles(
    entity_id,artifact_type,material_json,appearance_json,abilities_json,
    limitations_json,usage_conditions_json,creation_summary,fate_summary
