('artifact.chinese.five_colored_stones','NARRATIVE_MATERIAL','["stone"]','{"colors":5}','["used to patch the sky"]','[]','[]','Refined by Nüwa in both the Huainanzi Lan Ming and Liezi Tang Wen witnesses.','Used to repair the sky; no material object or cult relic is inferred.'),
('artifact.hindu.amrita','DIVINE_ELIXIR','["nectar"]','{}','["immortality"]','[]','[]','Produced by churning the ocean in both registered textual witnesses.','Seized by the asuras and recovered for the gods through Viṣṇu''s female form in both witnesses.');

INSERT OR IGNORE INTO text_profiles(
    entity_id,text_type,original_language_id,attributed_author,compiler,composition_period,
    earliest_extant_witness,chapter_structure,repository,shelfmark,copyright_status,summary
) VALUES
('text.chinese.liezi','PHILOSOPHICAL_COMPENDIUM','lang.lzh','Attributed to Lie Yukou',NULL,'Attributed Warring States; date of the received compilation debated',NULL,'Eight chapters in the received text','Chinese Text Project bibliography links received editions',NULL,'Ancient text public domain; digital edition terms apply','Received compendium whose Tang Wen chapter contains the Nüwa repair followed by the Gonggong episode.'),
('text.chinese.huainanzi.lanming_nuwa_passage','RECEIVED_CLASSICAL_PASSAGE','lang.lzh',NULL,'Compiled under Liu An','Western Han',NULL,'Lan Ming Xun, passage opening with the collapse of the four poles','Chinese Text Project',NULL,'Ancient text public domain; digital edition terms apply','Cosmic collapse, five-colored stones, the turtle''s legs, the black dragon and reed ash.'),
('text.chinese.huainanzi.tianwen_gonggong_passage','RECEIVED_CLASSICAL_PASSAGE','lang.lzh',NULL,'Compiled under Liu An','Western Han',NULL,'Tian Wen Xun, Gonggong and Mount Buzhou passage','Chinese Text Project',NULL,'Ancient text public domain; digital edition terms apply','Gonggong contends with Zhuanxu, strikes Mount Buzhou, and heaven and earth tilt.'),
('text.chinese.liezi.tangwen_nuwa_gonggong_passage','RECEIVED_CLASSICAL_PASSAGE','lang.lzh','Attributed to Lie Yukou',NULL,'Received Liezi; compilation date debated',NULL,'Tang Wen, Tang–Xia Ge dialogue','Chinese Text Project',NULL,'Ancient text public domain; digital edition terms apply','Heaven and earth as deficient things, Nüwa''s repair, then the Gonggong episode.'),
('text.indian.mahabharata.adiparvan_churning','CRITICAL_EDITION_PASSAGE','lang.san','Traditional attribution to Vyāsa','BORI critical edition, ed. V. S. Sukthankar et al.','Layered epic composition; critical edition published 1933','Constituted text of the critical edition','Ādiparvan 1.15–1.17 within the Āstīkaparvan','GRETIL / University of Goettingen',NULL,'Reference use; source-file rights apply','Gods seek the amṛta, Mandara and Vāsuki, the tortoise king Akūpāra, Dhanvantari, the deluding female form, Rāhu and the battle.'),
('text.hindu.bhagavata_purana','PURANA','lang.san',NULL,NULL,'Scholarly dating varies; commonly placed in the late first millennium CE',NULL,'Twelve skandhas','GRETIL / University of Goettingen',NULL,'Reference use; source-file rights apply','Purāṇa that remains scripture in living devotional traditions; the churning appears in Skandha 8.'),
('text.hindu.bhagavata_purana.skandha8_churning','PURANIC_PASSAGE','lang.san',NULL,NULL,'Scholarly dating varies',NULL,'Skandha 8, adhyāyas 5–9','GRETIL / University of Goettingen',NULL,'Reference use; source-file rights apply','Truce, uprooting of Mandara, Viṣṇu as tortoise, Śiva drinks the poison, Dhanvantari, Mohinī and Rāhu.');

