INSERT OR IGNORE INTO myth_event_profiles(
    entity_id,event_type,time_layer,cause_summary,process_summary,result_summary,symbolism_summary
) VALUES
('event.chinese.nuwa_repairs_sky','COSMIC_REPAIR','Huainanzi Lan Ming and Liezi Tang Wen witnesses','Huainanzi describes the four poles collapsing and the nine provinces splitting; Liezi frames heaven and earth as deficient things.','Nüwa refines five-colored stones and cuts the turtle''s legs to set up the four poles; Huainanzi adds the black dragon and reed ash.','Heaven and earth are made whole again in the Huainanzi witness.','Neither registered witness makes Gonggong''s collision the cause of the repair; later causal retellings are queued separately.'),
('event.chinese.gonggong_strikes_buzhou','COSMOLOGICAL_ETIOLOGY','Huainanzi Tian Wen and Liezi Tang Wen witnesses','Gonggong contends with Zhuanxu for rulership.','In anger he strikes Mount Buzhou, breaking the pillar of heaven and the cords of the earth.','Heaven tilts to the northwest and the earth sinks to the southeast.','Huainanzi Tian Wen narrates the episode on its own; Liezi places it after Nüwa''s repair.'),
('event.hindu.samudra_manthana','COSMIC_CHURNING','Mahābhārata critical edition and Bhāgavata Purāṇa witnesses','Gods seek the amṛta and, with the asuras, churn the ocean.','Mount Mandara serves as the rod and Vāsuki as the rope; the witnesses differ on who supports the mountain and on the poison episode.','Dhanvantari emerges with the amṛta, which Viṣṇu''s female form secures for the gods; Rāhu is beheaded.','The Angkor Wat relief is linked only as a separate material witness; its recension is not inferred from these texts.');

