('claim.v0300.nuwa.lanming_collapse','event.chinese.nuwa_repairs_sky','NARRATIVE_CONDITION',NULL,'The four poles collapse, the nine provinces split, and fire and floods rage unchecked.','STRING','The Huainanzi Lan Ming witness opens the episode with the collapse of the four poles and the splitting of the nine provinces.','v0300.china.nuwa.cause','SUPPORTED',0.96,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Huainanzi Lan Ming witness',NULL,'No named agent of the collapse is supplied in this passage.','2026-10-02T05:40:00Z'),
('claim.v0300.nuwa.liezi_deficiency_frame','text.chinese.liezi.tangwen_nuwa_gonggong_passage','FRAMES_AS',NULL,'Heaven and earth are also things; things have deficiencies, so Nüwa mended the gap.','STRING','The Liezi Tang Wen witness frames the repair inside a dialogue on whether heaven and earth, as things, have deficiencies.','v0300.china.nuwa.cause','SUPPORTED',0.95,'HIGH','VERIFIED','TEXT_SAYS','TEXTUAL_WITNESS','Liezi Tang Wen witness',NULL,'Dialogue between Tang of Yin and Xia Ge.','2026-10-02T05:40:00Z'),
('claim.v0300.nuwa.participates','deity.chinese.nu_wa','PARTICIPATED_IN','event.chinese.nuwa_repairs_sky',NULL,NULL,'Nüwa is the actor who repairs the sky in both registered witnesses.','v0300.china.nuwa.repair','SUPPORTED',0.98,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Huainanzi and Liezi witnesses',NULL,'Liezi uses the designation 女媧氏.','2026-10-02T05:40:00Z'),
('claim.v0300.nuwa.uses_stones','deity.chinese.nu_wa','USES','artifact.chinese.five_colored_stones',NULL,NULL,'Nüwa refines five-colored stones to repair the sky in both registered witnesses.','v0300.china.nuwa.repair','SUPPORTED',0.97,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Huainanzi and Liezi witnesses',NULL,'Glyph variants of the refining verb do not change the summary.','2026-10-02T05:40:00Z'),
('claim.v0300.nuwa.ao_legs','creature.chinese.ao_turtle','USED_AS',NULL,'legs cut off to set up the four poles','STRING','Both registered witnesses say that the great turtle''s legs are cut off to set up the four poles.','v0300.china.nuwa.repair','SUPPORTED',0.96,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Huainanzi and Liezi witnesses',NULL,'Glyph variants 鼇／鰲 occur across editions.','2026-10-02T05:40:00Z'),
('claim.v0300.nuwa.kills_black_dragon','deity.chinese.nu_wa','KILLED','dragon.chinese.black_dragon_jizhou',NULL,NULL,'In the Huainanzi Lan Ming witness Nüwa kills a black dragon to relieve Jizhou.','v0300.china.nuwa.huainanzi_only','SUPPORTED',0.95,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Huainanzi Lan Ming witness',NULL,'Not stated in the Liezi Tang Wen witness.','2026-10-02T05:40:00Z'),
('claim.v0300.nuwa.reed_ash','deity.chinese.nu_wa','NARRATIVE_ACTION',NULL,'Piles up reed ash to stop the flood waters.','STRING','In the Huainanzi Lan Ming witness Nüwa piles up reed ash to stop the flood waters.','v0300.china.nuwa.huainanzi_only','SUPPORTED',0.95,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Huainanzi Lan Ming witness',NULL,'Not stated in the Liezi Tang Wen witness.','2026-10-02T05:40:00Z'),
('claim.v0300.nuwa.lanming_gonggong_boundary','event.chinese.nuwa_repairs_sky','EVIDENCE_SCOPE',NULL,'Huainanzi Lan Ming names no agent of the collapse; Gonggong''s collision appears separately in Huainanzi Tian Wen.','STRING','The Lan Ming Nüwa passage does not attribute the collapse to Gonggong; the Gonggong collision is narrated in a different Huainanzi chapter and is not spliced into this witness.','v0300.china.nuwa.boundary','INTERPRETIVE',0.95,'HIGH','VERIFIED','SCHOLARLY_INTERPRETATION','SCHOLARLY_INTERPRETATION','Editorial witness boundary',NULL,'NOT_STATED is a scope note, not a negative claim about other texts.','2026-10-02T05:40:00Z'),
('claim.v0300.nuwa.causal_link_boundary','event.chinese.nuwa_repairs_sky','SOURCE_LAYER_BOUNDARY',NULL,'Neither registered early witness makes Gonggong''s collision the cause of Nüwa''s repair; later causal retellings form a separate reception layer.','STRING','The popular sequence in which Gonggong''s collision causes Nüwa''s repair is not back-projected into the Huainanzi or Liezi witnesses and is queued as a later reception layer.','v0300.china.nuwa.boundary','INTERPRETIVE',0.94,'HIGH','VERIFIED','SCHOLARLY_INTERPRETATION','SCHOLARLY_INTERPRETATION','Editorial witness boundary',NULL,'Later witnesses must be registered with exact locators before any causal link is modeled.','2026-10-02T05:40:00Z'),
('claim.v0300.gonggong.contends_zhuanxu','deity.chinese.gonggong','CONTENDED_WITH','hero.chinese.zhuanxu',NULL,NULL,'Gonggong contends with Zhuanxu to become ruler in both registered witnesses.','v0300.china.gonggong.episode','SUPPORTED',0.97,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Huainanzi Tian Wen and Liezi Tang Wen witnesses',NULL,'Liezi uses the designation 共工氏.','2026-10-02T05:40:00Z'),
