('claim.v0300.gonggong.strikes_buzhou','deity.chinese.gonggong','STRUCK','place.chinese.buzhou_mountain',NULL,NULL,'In anger Gonggong strikes Mount Buzhou, breaking the pillar of heaven and snapping the cords of the earth.','v0300.china.gonggong.episode','SUPPORTED',0.97,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Huainanzi Tian Wen and Liezi Tang Wen witnesses',NULL,'Word order differs slightly between the witnesses.','2026-10-02T05:40:00Z'),
('claim.v0300.gonggong.tilt_etiology','event.chinese.gonggong_strikes_buzhou','EXPLAINS',NULL,'Heaven tilts to the northwest and the earth falls short in the southeast, where waters gather.','STRING','Both registered witnesses use the collision to explain why heaven tilts northwest and waters flow to the southeast.','v0300.china.gonggong.etiology','SUPPORTED',0.96,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Huainanzi Tian Wen and Liezi Tang Wen witnesses',NULL,'Mythic etiology, not a geographical or astronomical finding.','2026-10-02T05:40:00Z'),
