('evidence.v0300.churn.relief_mbh','claim.v0300.churn.relief_recension_boundary','source.india.mahabharata.adiparvan.gretil','Mahābhārata CE, Ādiparvan 1.15–1.17 — separate textual layer','1.15–1.17',NULL,NULL,NULL,'MBh_CE_1.15-1.17',NULL,'PRIMARY_TEXT','CONTEXT',0.95,'Textual witness kept separate.'),
('evidence.v0300.churn.relief_bhp','claim.v0300.churn.relief_recension_boundary','source.india.bhagavatapurana.gretil','Bhāgavatapurāṇa 8.5–8.9 — separate textual layer','8.5–8.9',NULL,NULL,NULL,'BhP_8.5-8.9',NULL,'PRIMARY_TEXT','CONTEXT',0.95,'Textual witness kept separate.');

