INSERT OR IGNORE INTO conflicts(
    id,subject_id,variant_group,claim_a_id,claim_b_id,conflict_type,status,summary,resolution_notes
) VALUES
('conflict.v0300.hindu.churning_tortoise_support','place.hindu.mandara','v0300.india.churning.tortoise_support','claim.v0300.churn.akupara_supports','claim.v0300.churn.kurma_supports','WITNESS_VARIANT','OPEN','The Mahābhārata critical edition (Ādiparvan 1.16) has the tortoise king Akūpāra bear Mount Mandara, while the Bhāgavata Purāṇa (8.7) has Viṣṇu himself assume a tortoise form to raise it.','Retain both as coexisting textual witnesses. Akūpāra and Kūrma remain separate entities; no identity claim is made without an explicit source-backed identification.'),
('conflict.v0300.china.gonggong_placement','event.chinese.gonggong_strikes_buzhou','v0300.china.gonggong.placement','claim.v0300.gonggong.liezi_after_nuwa','claim.v0300.gonggong.tianwen_standalone','NARRATIVE_SEQUENCE_VARIANT','OPEN','Liezi Tang Wen places the Gonggong collision after Nüwa''s repair, while Huainanzi Tian Wen narrates it as a standalone cosmological etiology without Nüwa.','Keep both placements. Do not adopt the later retelling in which the collision causes the repair until that reception layer is registered with exact locators.');

INSERT OR IGNORE INTO stories(
    id,canonical_title,title_zh,story_type,primary_civilization_id,summary_zh,summary_en,
    themes_json,evidence_status,access_level,reading_minutes,featured_order,
    editorial_note,created_at,updated_at
) VALUES
('story.chinese.nuwa_repairs_sky','Nüwa repairs the sky — Huainanzi and Liezi witnesses','女娲补天：《淮南子》与《列子》两种见证','MYTHIC_NARRATIVE','civ.chinese_ancient','《淮南子·览冥训》与《列子·汤问》都记载女娲炼五色石、断鳌足立四极；前者另有黑龙与芦灰，后者把补天放在天地“物有不足”的问答里，并在其后才引出共工。两份见证分开阅读，不合成后世“共工撞山导致女娲补天”的版本。','Huainanzi “Lan Ming” and Liezi “Tang Wen” both have Nüwa refine five-colored stones and cut a turtle''s legs to set up the four poles; the former adds the black dragon and reed ash, while the latter frames the repair as a remedy for deficient things and introduces Gonggong only afterwards. The two witnesses are read separately and are not merged into the later version in which Gonggong''s collision causes the repair.','["女娲","补天","宇宙修复","见证分离"]','SOURCE_BACKED','PUBLIC_CONTEXT',6,250,'两份传世文献逐段并列；《列子》传世本成书年代有争议，不据此排序。后世因果化的复述作为独立接受层排队。','2026-10-02T05:40:00Z','2026-10-02T05:40:00Z'),
('story.chinese.gonggong_buzhou','Gonggong strikes Mount Buzhou — two early witnesses','共工触不周山：天倾西北的两处见证','MYTHIC_NARRATIVE','civ.chinese_ancient','《淮南子·天文训》把共工与颛顼争帝、怒触不周山写成独立的天地倾斜起源；《列子·汤问》则用“其后”把同一事件接在女娲补天之后。两处见证都不把它写成女娲补天的起因。','Huainanzi “Tian Wen” narrates Gonggong contending with Zhuanxu and striking Mount Buzhou as a standalone explanation of why heaven and earth tilt; Liezi “Tang Wen” attaches the same event after Nüwa''s repair with “afterwards”. Neither witness makes it the cause of Nüwa''s repair.','["共工","不周山","天倾西北","起源解释"]','SOURCE_BACKED','PUBLIC_CONTEXT',4,260,'事件位置差异进入显式冲突档案；不周山不投射为现实坐标，颛顼不作历史真实性判断。','2026-10-02T05:40:00Z','2026-10-02T05:40:00Z'),
('story.hindu.samudra_manthana_texts','Churning of the Ocean — Mahābhārata critical edition and Bhāgavata Purāṇa witnesses','乳海搅拌：《摩诃婆罗多》精校本与《薄伽梵往世书》','MYTHIC_NARRATIVE','civ.hindu','两份梵语见证都以曼陀罗山为搅棒、婆苏吉为搅绳，并让檀文陀利捧着甘露出现、罗睺被神盘斩首；但托山的龟在精校本中是龟王阿库帕拉，在《薄伽梵往世书》中是毗湿奴的龟形化身，湿婆饮毒也只见于后者的当前定位。吴哥寺浮雕继续作为独立的物质见证。','Both Sanskrit witnesses use Mount Mandara as the rod and Vāsuki as the rope, have Dhanvantari emerge with the amṛta and Rāhu beheaded by the discus; but the tortoise supporting the mountain is the tortoise king Akūpāra in the critical edition and Viṣṇu''s tortoise form in the Bhāgavata Purāṇa, and Śiva drinking the poison appears only at the latter''s locator. The Angkor Wat relief remains a separate material witness.','["乳海搅拌","甘露","毗湿奴","见证差异","梵语文本"]','SOURCE_BACKED','PUBLIC_CONTEXT',8,270,'精校本正文与往世书分开对读；“未陈述”不等于所有写本都没有。现代虔信译本不复制，神学解释不作裁定。','2026-10-02T05:40:00Z','2026-10-02T05:40:00Z');

INSERT OR IGNORE INTO story_versions(
    id,story_id,version_label_zh,version_label_en,source_id,source_location,
    language_id,witness_scope,narrative_scope,evidence_status,access_level,
    version_order,rights_note,created_at
) VALUES
('storyver.chinese.nuwa_huainanzi_lanming','story.chinese.nuwa_repairs_sky','《淮南子·览冥训》见证','Huainanzi Lan Ming witness','source.china.huainanzi.lanmingxun.ctext','Huainanzi, Lan Ming Xun — passage opening 往古之時','lang.lzh','西汉刘安主持编纂的《淮南子》传世本；Chinese Text Project 数字版章节定位','四极崩坏、炼石补天、断鳌足、杀黑龙、积芦灰；不含共工','SOURCE_BACKED','PUBLIC_CONTEXT',1,'古籍原文属公共领域；数字版遵循网站条款。本站只发布定位与独立概述。','2026-10-02T05:40:00Z'),
('storyver.chinese.nuwa_liezi_tangwen','story.chinese.nuwa_repairs_sky','《列子·汤问》见证','Liezi Tang Wen witness','source.china.liezi.tangwen.ctext','Liezi, Tang Wen — Tang and Xia Ge dialogue','lang.lzh','托名列御寇的《列子》传世本，成书年代有争议；Chinese Text Project 数字版章节定位','天地亦物、炼石补阙、断鳌足立四极，其后共工触山与天倾西北','SOURCE_BACKED','PUBLIC_CONTEXT',2,'古籍原文属公共领域；数字版遵循网站条款。本站只发布定位与独立概述。','2026-10-02T05:40:00Z'),
('storyver.chinese.gonggong_huainanzi_tianwen','story.chinese.gonggong_buzhou','《淮南子·天文训》见证','Huainanzi Tian Wen witness','source.china.huainanzi.tianwenxun.ctext','Huainanzi, Tian Wen Xun — passage opening 昔者共工','lang.lzh','《淮南子·天文训》中的天地形势起源段落','共工与颛顼争帝、触不周山、天倾西北与地不满东南；不含女娲','SOURCE_BACKED','PUBLIC_CONTEXT',1,'古籍原文属公共领域；数字版遵循网站条款。本站只发布定位与独立概述。','2026-10-02T05:40:00Z'),
('storyver.chinese.gonggong_liezi_tangwen','story.chinese.gonggong_buzhou','《列子·汤问》见证','Liezi Tang Wen witness','source.china.liezi.tangwen.ctext','Liezi, Tang Wen — sentence opening 其後共工氏','lang.lzh','《列子·汤问》中紧接女娲补天之后的共工段落','以“其后”接续、共工氏与颛顼争帝、触山与天倾西北','SOURCE_BACKED','PUBLIC_CONTEXT',2,'古籍原文属公共领域；数字版遵循网站条款。本站只发布定位与独立概述。','2026-10-02T05:40:00Z'),
('storyver.hindu.churning_mbh_ce','story.hindu.samudra_manthana_texts','《摩诃婆罗多》精校本初篇 1.15–1.17','Mahābhārata critical edition, Ādiparvan 1.15–1.17','source.india.mahabharata.adiparvan.gretil','Mahābhārata CE, Ādiparvan 1.15–1.17 (Āstīkaparvan)','lang.san','班达卡尔东方研究所精校本的正文（GRETIL 电子转写）；只代表一种学术重建见证','诸神求甘露、阿难陀拔山、婆苏吉为绳、龟王阿库帕拉托山、檀文陀利、迷惑女身、罗睺与诸神之战','SOURCE_BACKED','PUBLIC_CONTEXT',1,'只发布定位、元数据与独立概述；GRETIL 文件条款与现代译本版权另行适用。','2026-10-02T05:40:00Z'),
('storyver.hindu.churning_bhagavata','story.hindu.samudra_manthana_texts','《薄伽梵往世书》8.5–8.9','Bhāgavata Purāṇa 8.5–8.9','source.india.bhagavatapurana.gretil','Bhāgavatapurāṇa, Skandha 8, adhyāyas 5–9','lang.san','仍在虔信传统中使用的往世书经文（GRETIL 电子转写）','诸神与阿修罗结盟拔山、毗湿奴化龟托山、湿婆饮毒、檀文陀利、摩希尼与罗睺','SOURCE_BACKED','PUBLIC_CONTEXT',2,'活态经典：只发布定位与描述性概述，不裁定神学或仪轨，不复制现代虔信译本。','2026-10-02T05:40:00Z');

INSERT OR IGNORE INTO story_sections(
    id,story_version_id,section_order,heading_zh,heading_en,body_zh,body_en,
    anchor_claim_id,evidence_note,uncertainty_note
) VALUES
('storysec.v0300.nuwa.lanming.1','storyver.chinese.nuwa_huainanzi_lanming',1,'四极废，九州裂','The four poles collapse','《淮南子·览冥训》以远古为背景：支撑天地的四极崩坏，九州开裂，天不能全覆、地不能全载，大火与洪水都无法止息，猛兽鸷鸟危害百姓。本段只按这一见证的顺序概述，不补入其他文献给出的起因。','Huainanzi “Lan Ming” sets the scene in remote antiquity: the four poles holding up the world have failed and the nine provinces have split; heaven no longer covers everything and earth no longer bears everything, fires and floods cannot be stopped, and wild beasts and birds of prey attack the people. This section follows only this witness and adds no cause taken from other texts.','claim.v0300.nuwa.lanming_collapse','《淮南子·览冥训》“往古之时”段；Chinese Text Project 章节页。','传世本用字存在异体；本站只发布独立概述，不复制整段原文。'),
('storysec.v0300.nuwa.lanming.2','storyver.chinese.nuwa_huainanzi_lanming',2,'炼五色石，断鳌足','Five-colored stones and the turtle''s legs','于是女娲炼五色石来修补苍天，又截断巨鳌的足，用来重新立起四极。','Nüwa then refines five-colored stones to patch the azure sky and cuts off the legs of a great turtle to set the four poles upright again.','claim.v0300.nuwa.uses_stones','同段女娲补天与立四极的句组。','炼字与鳌字在不同版本中有异体，不影响本段概述。'),
('storysec.v0300.nuwa.lanming.3','storyver.chinese.nuwa_huainanzi_lanming',3,'杀黑龙，积芦灰','The black dragon and the reed ash','这一见证还写到女娲杀死黑龙以救济冀州，并堆积芦苇灰来堵住泛滥的洪水；随后天地重新安定，百姓得以存活。','This witness adds that Nüwa kills a black dragon to relieve Jizhou and piles up reed ash to stop the flood waters; afterwards heaven and earth are set right and the people survive.','claim.v0300.nuwa.kills_black_dragon','同段黑龙、冀州与芦灰句组。','冀州在此是文本中的九州之一，不映射为现代行政区或坐标；《列子·汤问》对应段落未陈述这两项。'),
('storysec.v0300.nuwa.lanming.4','storyver.chinese.nuwa_huainanzi_lanming',4,'这一段没有写共工','No Gonggong in this passage','《览冥训》的女娲段落没有把天地崩坏归因于共工。《淮南子》确实在《天文训》另记共工怒触不周山，但那是另一章中独立的天地倾斜起源，本站不把两章拼接成因果链。','The Lan Ming Nüwa passage does not attribute the collapse to Gonggong. The Huainanzi does narrate Gonggong striking Mount Buzhou, but in a separate passage in the “Tian Wen” chapter that explains the tilt of heaven and earth; the site does not splice the two chapters into a causal chain.','claim.v0300.nuwa.lanming_gonggong_boundary','《览冥训》女娲段与《天文训》共工段分别定位。','把共工触山写成女娲补天起因的说法见于较晚文献，已作为独立接受层排队。'),
('storysec.v0300.nuwa.liezi.1','storyver.chinese.nuwa_liezi_tangwen',1,'天地也是“物”','Heaven and earth are also things','《列子·汤问》把女娲补天放在殷汤与夏革关于天地有无极限的问答中：天地也是物，物都有不足之处，所以古时女娲修补了它的缺口。','Liezi “Tang Wen” places the repair inside a dialogue between Tang of Yin and Xia Ge on whether heaven and earth have limits: heaven and earth are also things, things have deficiencies, and so in antiquity Nüwa mended the gap.','claim.v0300.nuwa.liezi_deficiency_frame','《列子·汤问》殷汤与夏革问答段。','《列子》托名列御寇，传世本成书年代有争议；本站不据此把它排在《淮南子》之前。'),
('storysec.v0300.nuwa.liezi.2','storyver.chinese.nuwa_liezi_tangwen',2,'五色石与鳌足','Five-colored stones and the turtle''s legs','这一见证同样写女娲炼五色石补其缺口，并截断鳌足以立四极；它没有写黑龙、冀州或芦灰。','This witness likewise has Nüwa refine five-colored stones to fill the gap and cut the turtle''s legs to set up the four poles; it does not mention the black dragon, Jizhou or reed ash.','claim.v0300.nuwa.uses_stones','《列子·汤问》女娲句组。','“未陈述”只描述本段范围，不是对《淮南子》细节的否定。'),
('storysec.v0300.nuwa.liezi.3','storyver.chinese.nuwa_liezi_tangwen',3,'“其后”才是共工','Gonggong comes “afterwards”','紧接补天之后，《汤问》用“其后”引出共工氏与颛顼争为帝、怒触不周之山。在这一见证里，共工事件发生在女娲补天之后，而不是它的起因。','Right after the repair, “Tang Wen” uses “afterwards” to introduce Gonggong contending with Zhuanxu for rulership and striking Mount Buzhou in anger. In this witness the Gonggong episode follows Nüwa''s repair; it is not its cause.','claim.v0300.gonggong.liezi_after_nuwa','《列子·汤问》“其后共工氏”句。','后世“共工触山导致女娲补天”的因果顺序不回写进本见证。'),
('storysec.v0300.nuwa.liezi.4','storyver.chinese.nuwa_liezi_tangwen',4,'天倾西北，水归东南','Heaven tilts northwest, waters gather southeast','共工撞山折断天柱、断绝地维，于是天向西北倾斜，日月星辰向那里移动；地在东南不满，众水因此流归东南。','Gonggong''s blow breaks the pillar of heaven and snaps the cords of the earth, so heaven tilts toward the northwest, where the sun, moon and stars move, and the earth falls short in the southeast, where the rivers and flood waters gather.','claim.v0300.gonggong.tilt_etiology','《列子·汤问》天倾西北句组。','这是文本中的天地形势起源解释，不作为地理或天文史实。'),
('storysec.v0300.gonggong.tianwen.1','storyver.chinese.gonggong_huainanzi_tianwen',1,'共工与颛顼争为帝','Gonggong contends with Zhuanxu','《淮南子·天文训》说，从前共工与颛顼争夺帝位。','Huainanzi “Tian Wen” says that long ago Gonggong contended with Zhuanxu to become ruler.','claim.v0300.gonggong.contends_zhuanxu','《淮南子·天文训》“昔者共工”段。','颛顼在此作为传说中的君主登记，不作历史真实性判断。'),
('storysec.v0300.gonggong.tianwen.2','storyver.chinese.gonggong_huainanzi_tianwen',2,'怒触不周之山','Striking Mount Buzhou in anger','共工发怒撞向不周山，支撑天的柱子折断，系住大地的绳索断绝。','In anger Gonggong strikes Mount Buzhou; the pillar holding up heaven breaks and the cords binding the earth snap.','claim.v0300.gonggong.strikes_buzhou','同段不周山、天柱与地维句组。','不周山不映射为现代山名或坐标。'),
('storysec.v0300.gonggong.tianwen.3','storyver.chinese.gonggong_huainanzi_tianwen',3,'一段独立的起源解释','A standalone etiology','结果天向西北倾斜，日月星辰随之移动；地在东南不满，积水与尘埃都归向那里。这一段没有提到女娲，是《天文训》中独立的天地形势解释。','As a result heaven tilts to the northwest and the sun, moon and stars shift with it; the earth falls short in the southeast, where waters and dust collect. The passage does not mention Nüwa and stands as an independent explanation of cosmic orientation in “Tian Wen”.','claim.v0300.gonggong.tianwen_standalone','《淮南子·天文训》共工段结尾。','同书《览冥训》的女娲段与此段分属不同章节，不合成单一故事。'),
('storysec.v0300.gonggong.liezi.1','storyver.chinese.gonggong_liezi_tangwen',1,'接在女娲补天之后','Following Nüwa''s repair','《列子·汤问》在叙述女娲补天之后，用“其后”转入共工的故事，因此这一见证中的共工事件有明确的先后位置。','Liezi “Tang Wen” turns to Gonggong with “afterwards” right after narrating Nüwa''s repair, so in this witness the Gonggong episode has an explicit place in sequence.','claim.v0300.gonggong.liezi_after_nuwa','《列子·汤问》“其后共工氏”句。','叙事先后只属于这一见证，不是绝对年代。'),
('storysec.v0300.gonggong.liezi.2','storyver.chinese.gonggong_liezi_tangwen',2,'共工氏与颛顼争帝','Gonggong-shi contends with Zhuanxu','这里称“共工氏”，同样与颛顼争为帝，怒而撞向不周之山，折断天柱、断绝地维。','Here he is called “Gonggong-shi”; again he contends with Zhuanxu for rulership and strikes Mount Buzhou in anger, breaking the pillar of heaven and snapping the cords of the earth.','claim.v0300.gonggong.strikes_buzhou','《列子·汤问》共工氏句组。','“共工”与“共工氏”的称谓差异保留，不判定其为神祇、氏族首领或二者兼有。'),
('storysec.v0300.gonggong.liezi.3','storyver.chinese.gonggong_liezi_tangwen',3,'天倾西北，百川东归','Heaven tilts northwest, rivers flow southeast','天向西北倾斜，日月星辰向那里靠拢；地在东南不满，于是百川与积水都流归东南。与《天文训》相比，措辞略有不同。','Heaven tilts to the northwest and the sun, moon and stars draw toward it; the earth falls short in the southeast, so all rivers and flood waters flow there. The wording differs slightly from “Tian Wen”.','claim.v0300.gonggong.tilt_etiology','《列子·汤问》天倾西北句组。','措辞差异只在对读中标注，不改写任一见证。'),
('storysec.v0300.churn.mbh.1','storyver.hindu.churning_mbh_ce',1,'诸神求取甘露','The gods seek the amṛta','精校本《初篇》1.15 中，诸神聚集在须弥山上商议如何得到甘露；那罗延（毗湿奴）建议诸神与阿修罗一起搅动大海。','In the critical edition at Ādiparvan 1.15, the gods gather on Mount Meru to deliberate how to obtain the amṛta; Nārāyaṇa (Viṣṇu) advises that gods and asuras churn the ocean together.','claim.v0300.churn.amrita_sought','精校本初篇 1.15。','“那罗延”在此按既有毗湿奴实体连接，不扩展神学解释。'),
('storysec.v0300.churn.mbh.2','storyver.hindu.churning_mbh_ce',2,'曼陀罗山、婆苏吉与龟王','Mandara, Vāsuki and the tortoise king','巨蛇阿难陀拔起曼陀罗山作为搅棒，龙王婆苏吉充当搅绳；山的底部由龟王阿库帕拉承托。这一见证没有说龟王是毗湿奴的化身。','The serpent Ananta uproots Mount Mandara to serve as the churning rod and the nāga Vāsuki serves as the rope; the tortoise king Akūpāra bears the base of the mountain. This witness does not say that the tortoise king is a form of Viṣṇu.','claim.v0300.churn.akupara_supports','精校本初篇 1.16。','阿难陀拔山一项为中等置信度，待逐颂校对；阿难陀尚未单独建实体。'),
('storysec.v0300.churn.mbh.3','storyver.hindu.churning_mbh_ce',3,'檀文陀利捧着甘露出现','Dhanvantari appears with the amṛta','搅拌中先后涌现多种存在与宝物，最后檀文陀利捧着盛满甘露的水罐出现。','As the churning goes on, a series of beings and treasures emerges, and finally Dhanvantari appears holding a vessel filled with the amṛta.','claim.v0300.churn.dhanvantari_carries_amrita','精校本初篇 1.16。','此前出现之物的逐项清单尚未建模，不从其他版本补齐。'),
('storysec.v0300.churn.mbh.4','storyver.hindu.churning_mbh_ce',4,'迷惑的女身与罗睺','The deluding female form and Rāhu','阿修罗夺走甘露后，那罗延化作迷惑人的女子形象，把甘露取回交给诸神。罗睺假扮天神偷饮甘露，被日月揭发后，那罗延以神盘斩下其头；随后天神与阿修罗爆发大战。','After the Dānavas seize the amṛta, Nārāyaṇa takes on a deluding female form and recovers it for the gods. Rāhu, disguised as a god, drinks some of it; when the Sun and Moon expose him, Nārāyaṇa cuts off his head with the discus, and a great battle between gods and Dānavas follows.','claim.v0300.churn.rahu_beheaded','精校本初篇 1.16–1.17。','专名实体“摩希尼”只连接《薄伽梵往世书》见证；此处保留“迷惑的女身”描述。'),
('storysec.v0300.churn.mbh.5','storyver.hindu.churning_mbh_ce',5,'精校本正文的范围','Scope of the constituted critical text','在精校本 1.15–1.17 的正文里，没有湿婆吞下毒药的情节。这只说明本定位“未陈述”，不代表所有写本或地方传统都没有；校勘记录与附录尚待逐项核对。','The constituted critical text at 1.15–1.17 does not include Śiva swallowing the poison. This records only that the locator does not state it; it does not mean that every manuscript or regional tradition lacks it, and the apparatus and appendices still have to be checked.','claim.v0300.churn.mbh_poison_scope','精校本初篇 1.15–1.17 正文范围与 BORI 精校本说明。','写本校勘与附录已作为独立研究队列排队。'),
('storysec.v0300.churn.bhp.1','storyver.hindu.churning_bhagavata',1,'诸神与阿修罗暂时结盟','A truce between gods and asuras','《薄伽梵往世书》第八篇第5–6章中，诸神按毗湿奴的建议与阿修罗暂时结盟，合力拔起曼陀罗山并运往大海，毗湿奴亲自出手相助。','In Bhāgavata Purāṇa 8.5–8.6, on Viṣṇu''s advice the gods make a temporary truce with the asuras; together they uproot Mount Mandara and carry it toward the ocean, with Viṣṇu himself stepping in to help.','claim.v0300.churn.bhp_devas_asuras_uproot','《薄伽梵往世书》8.5–8.6。','运山过程的细节只作概述，待逐颂校对。'),
('storysec.v0300.churn.bhp.2','storyver.hindu.churning_bhagavata',2,'毗湿奴化身巨龟','Viṣṇu takes the form of a tortoise','以婆苏吉为绳开始搅拌后，曼陀罗山沉入水中；毗湿奴化作巨龟潜到山下，用背托起大山。','Once the churning begins with Vāsuki as the rope, Mount Mandara sinks into the water; Viṣṇu assumes the form of a giant tortoise, dives beneath it and raises the mountain on his back.','claim.v0300.churn.kurma_supports','《薄伽梵往世书》8.7。','与精校本的龟王阿库帕拉构成显式见证差异，不做身份等同。'),
('storysec.v0300.churn.bhp.3','storyver.hindu.churning_bhagavata',3,'湿婆饮下毒药','Śiva drinks the poison','搅拌最先产生可怕的毒药，向各方蔓延；众生求助于湿婆，湿婆把毒药饮下。','The churning first produces a terrible poison that spreads in every direction; beings turn to Śiva, who drinks it.','claim.v0300.churn.shiva_drinks_poison','《薄伽梵往世书》8.7。','后续图像传统与虔信解释未在本批次逐句建模。'),
('storysec.v0300.churn.bhp.4','storyver.hindu.churning_bhagavata',4,'檀文陀利与甘露','Dhanvantari and the amṛta','其后又涌现多种宝物与存在，最后檀文陀利捧着盛满甘露的水罐出现。','A series of treasures and beings then emerges, and finally Dhanvantari appears holding a vessel filled with the amṛta.','claim.v0300.churn.dhanvantari_carries_amrita','《薄伽梵往世书》8.8。','此前出现之物的逐项清单尚未建模，不与精校本合并。'),
('storysec.v0300.churn.bhp.5','storyver.hindu.churning_bhagavata',5,'摩希尼与罗睺','Mohinī and Rāhu','阿修罗抢走甘露后，毗湿奴化身为摩希尼迷惑他们，并把甘露分给诸神。罗睺假扮天神混入其中饮下甘露，被日月指认后，毗湿奴以神盘斩下其头。','When the asuras snatch the amṛta, Viṣṇu becomes Mohinī, captivates them and distributes the amṛta to the gods. Rāhu, disguised as a god, slips in and drinks; when the Sun and Moon point him out, Viṣṇu severs his head with the discus.','claim.v0300.churn.mohini_distributes','《薄伽梵往世书》8.8–8.9。','罗睺后来的天体身份不在本批次建模。');

