INSERT OR IGNORE INTO story_event_nodes(
    id,story_version_id,event_order,title_zh,title_en,summary_zh,summary_en,
    anchor_claim_id,event_entity_id,place_entity_id,location_kind,coordinate_policy,
    evidence_status,uncertainty_note,created_at
) VALUES
('storyevent.v0300.nuwa.lanming.1','storyver.chinese.nuwa_huainanzi_lanming',1,'天地崩坏','Cosmic collapse','四极崩坏、九州开裂。','The four poles fail and the nine provinces split.','claim.v0300.nuwa.lanming_collapse','event.chinese.nuwa_repairs_sky',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','宇宙性的崩坏不投射为现实地点。','2026-10-02T05:40:00Z'),
('storyevent.v0300.nuwa.lanming.2','storyver.chinese.nuwa_huainanzi_lanming',2,'炼石补天、立四极','Patching the sky and setting the poles','女娲用五色石与鳌足修复天地。','Nüwa repairs the world with the stones and the turtle''s legs.','claim.v0300.nuwa.uses_stones','event.chinese.nuwa_repairs_sky',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-02T05:40:00Z'),
('storyevent.v0300.nuwa.lanming.3','storyver.chinese.nuwa_huainanzi_lanming',3,'救济冀州','Relief for Jizhou','杀黑龙、积芦灰止水。','The black dragon is killed and reed ash stops the floods.','claim.v0300.nuwa.kills_black_dragon','event.chinese.nuwa_repairs_sky',NULL,'TEXTUAL_PLACE','NO_COORDINATE','SOURCE_BACKED','冀州是文本中的九州之一，不映射为现代坐标。','2026-10-02T05:40:00Z'),
('storyevent.v0300.nuwa.lanming.4','storyver.chinese.nuwa_huainanzi_lanming',4,'见证边界','Witness boundary','本段不含共工，不与《天文训》拼接。','No Gonggong here; not spliced with “Tian Wen”.','claim.v0300.nuwa.lanming_gonggong_boundary','event.chinese.nuwa_repairs_sky',NULL,'UNSPECIFIED','NOT_APPLICABLE','SOURCE_BACKED','这是来源边界节点，不是新增神话动作。','2026-10-02T05:40:00Z'),
('storyevent.v0300.nuwa.liezi.1','storyver.chinese.nuwa_liezi_tangwen',1,'物有不足','Things have deficiencies','天地被视为有缺口的“物”。','Heaven and earth are treated as deficient things.','claim.v0300.nuwa.liezi_deficiency_frame','event.chinese.nuwa_repairs_sky',NULL,'UNSPECIFIED','NOT_APPLICABLE','SOURCE_BACKED','问答框架节点。','2026-10-02T05:40:00Z'),
('storyevent.v0300.nuwa.liezi.2','storyver.chinese.nuwa_liezi_tangwen',2,'炼石补阙','Mending the gap','女娲炼石补缺、断鳌足立四极。','Nüwa mends the gap and sets up the four poles.','claim.v0300.nuwa.uses_stones','event.chinese.nuwa_repairs_sky',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-02T05:40:00Z'),
('storyevent.v0300.nuwa.liezi.3','storyver.chinese.nuwa_liezi_tangwen',3,'其后共工触山','Afterwards, Gonggong strikes the mountain','共工事件接在补天之后。','The Gonggong episode follows the repair.','claim.v0300.gonggong.liezi_after_nuwa','event.chinese.gonggong_strikes_buzhou','place.chinese.buzhou_mountain','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','叙事先后不是绝对年代；不周山不投射坐标。','2026-10-02T05:40:00Z'),
('storyevent.v0300.nuwa.liezi.4','storyver.chinese.nuwa_liezi_tangwen',4,'天倾西北','Heaven tilts northwest','天地形势的起源解释。','Etiology of the tilt of heaven and earth.','claim.v0300.gonggong.tilt_etiology','event.chinese.gonggong_strikes_buzhou','place.chinese.buzhou_mountain','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','不作为地理或天文史实。','2026-10-02T05:40:00Z'),
('storyevent.v0300.gonggong.tianwen.1','storyver.chinese.gonggong_huainanzi_tianwen',1,'争为帝','Contest for rulership','共工与颛顼争帝。','Gonggong contends with Zhuanxu.','claim.v0300.gonggong.contends_zhuanxu','event.chinese.gonggong_strikes_buzhou',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','当前见证未定位争帝地点。','2026-10-02T05:40:00Z'),
('storyevent.v0300.gonggong.tianwen.2','storyver.chinese.gonggong_huainanzi_tianwen',2,'怒触不周山','Striking Mount Buzhou','天柱折、地维绝。','The pillar of heaven breaks and the cords of earth snap.','claim.v0300.gonggong.strikes_buzhou','event.chinese.gonggong_strikes_buzhou','place.chinese.buzhou_mountain','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','不周山不映射为现代山名。','2026-10-02T05:40:00Z'),
('storyevent.v0300.gonggong.tianwen.3','storyver.chinese.gonggong_huainanzi_tianwen',3,'独立的起源解释','Standalone etiology','天倾西北、地不满东南；不含女娲。','Heaven tilts northwest, earth falls short southeast; no Nüwa.','claim.v0300.gonggong.tianwen_standalone','event.chinese.gonggong_strikes_buzhou','place.chinese.buzhou_mountain','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','与《列子》的位置差异进入显式冲突档案。','2026-10-02T05:40:00Z'),
('storyevent.v0300.gonggong.liezi.1','storyver.chinese.gonggong_liezi_tangwen',1,'接续补天之后','After the repair','以“其后”接续女娲补天。','Introduced with “afterwards” after Nüwa''s repair.','claim.v0300.gonggong.liezi_after_nuwa','event.chinese.gonggong_strikes_buzhou',NULL,'UNSPECIFIED','NOT_APPLICABLE','SOURCE_BACKED','叙事先后节点。','2026-10-02T05:40:00Z'),
('storyevent.v0300.gonggong.liezi.2','storyver.chinese.gonggong_liezi_tangwen',2,'触不周之山','Striking Mount Buzhou','共工氏折天柱、绝地维。','Gonggong-shi breaks the pillar and snaps the cords.','claim.v0300.gonggong.strikes_buzhou','event.chinese.gonggong_strikes_buzhou','place.chinese.buzhou_mountain','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','不周山不映射为现代山名。','2026-10-02T05:40:00Z'),
('storyevent.v0300.gonggong.liezi.3','storyver.chinese.gonggong_liezi_tangwen',3,'百川东归','Rivers flow southeast','天倾西北，百川归东南。','Heaven tilts northwest; rivers flow southeast.','claim.v0300.gonggong.tilt_etiology','event.chinese.gonggong_strikes_buzhou','place.chinese.buzhou_mountain','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','措辞差异只在对读中标注。','2026-10-02T05:40:00Z'),
('storyevent.v0300.churn.mbh.1','storyver.hindu.churning_mbh_ce',1,'诸神议求甘露','The gods seek the amṛta','须弥山上的商议与搅海建议。','Deliberation on Mount Meru and the advice to churn.','claim.v0300.churn.amrita_sought','event.hindu.samudra_manthana',NULL,'MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','须弥山尚未建实体，不投射坐标。','2026-10-02T05:40:00Z'),
('storyevent.v0300.churn.mbh.2','storyver.hindu.churning_mbh_ce',2,'龟王托山','The tortoise king bears the mountain','曼陀罗山为棒、婆苏吉为绳、阿库帕拉托底。','Mandara as rod, Vāsuki as rope, Akūpāra as support.','claim.v0300.churn.akupara_supports','event.hindu.samudra_manthana','place.hindu.mandara','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','与《薄伽梵往世书》的托山者不同，见显式冲突。','2026-10-02T05:40:00Z'),
('storyevent.v0300.churn.mbh.3','storyver.hindu.churning_mbh_ce',3,'甘露出现','The amṛta appears','檀文陀利捧甘露而出。','Dhanvantari emerges with the amṛta.','claim.v0300.churn.dhanvantari_carries_amrita','event.hindu.samudra_manthana',NULL,'MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话海洋不投射为现实坐标。','2026-10-02T05:40:00Z'),
('storyevent.v0300.churn.mbh.4','storyver.hindu.churning_mbh_ce',4,'罗睺被斩首','Rāhu is beheaded','迷惑女身取回甘露，罗睺被神盘斩首。','A deluding female form recovers the amṛta; Rāhu is beheaded.','claim.v0300.churn.rahu_beheaded','event.hindu.samudra_manthana',NULL,'MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','后续战斗只作概述。','2026-10-02T05:40:00Z'),
('storyevent.v0300.churn.mbh.5','storyver.hindu.churning_mbh_ce',5,'精校本范围','Critical-text scope','湿婆饮毒在本定位未陈述。','Śiva drinking the poison is not stated at this locator.','claim.v0300.churn.mbh_poison_scope','event.hindu.samudra_manthana',NULL,'UNSPECIFIED','NOT_APPLICABLE','SOURCE_BACKED','这是来源边界节点，不是新增神话动作。','2026-10-02T05:40:00Z'),
('storyevent.v0300.churn.bhp.1','storyver.hindu.churning_bhagavata',1,'结盟拔山','Truce and uprooting','诸神与阿修罗合力拔起曼陀罗山。','Gods and asuras uproot Mount Mandara together.','claim.v0300.churn.bhp_devas_asuras_uproot','event.hindu.samudra_manthana','place.hindu.mandara','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','曼陀罗山不映射为现代山丘。','2026-10-02T05:40:00Z'),
('storyevent.v0300.churn.bhp.2','storyver.hindu.churning_bhagavata',2,'化龟托山','The tortoise form','毗湿奴化龟托起沉入水中的山。','Viṣṇu as a tortoise raises the sinking mountain.','claim.v0300.churn.kurma_supports','event.hindu.samudra_manthana','place.hindu.mandara','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','与精校本的龟王构成显式见证差异。','2026-10-02T05:40:00Z'),
('storyevent.v0300.churn.bhp.3','storyver.hindu.churning_bhagavata',3,'湿婆饮毒','Śiva drinks the poison','搅拌最先产生的毒药被湿婆饮下。','The first product of the churning, a poison, is drunk by Śiva.','claim.v0300.churn.shiva_drinks_poison','event.hindu.samudra_manthana',NULL,'MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','精校本当前定位未陈述此情节。','2026-10-02T05:40:00Z'),
('storyevent.v0300.churn.bhp.4','storyver.hindu.churning_bhagavata',4,'甘露出现','The amṛta appears','檀文陀利捧甘露而出。','Dhanvantari emerges with the amṛta.','claim.v0300.churn.dhanvantari_carries_amrita','event.hindu.samudra_manthana',NULL,'MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话海洋不投射为现实坐标。','2026-10-02T05:40:00Z'),
('storyevent.v0300.churn.bhp.5','storyver.hindu.churning_bhagavata',5,'摩希尼分甘露','Mohinī distributes the amṛta','摩希尼分甘露，罗睺被斩首。','Mohinī distributes the amṛta; Rāhu is beheaded.','claim.v0300.churn.mohini_distributes','event.hindu.samudra_manthana',NULL,'MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','罗睺后来的天体身份不在本批次建模。','2026-10-02T05:40:00Z');

INSERT OR IGNORE INTO story_witness_profiles(
    story_version_id,work_title_original,work_title_transliteration,
    witness_label_original,witness_label_transliteration,language_id,script_name,
    source_location,editorial_note_zh,editorial_note_en,rights_boundary,created_at
) VALUES
('storyver.chinese.nuwa_huainanzi_lanming','淮南子·覽冥訓','Huáinánzǐ · Lǎnmíng xùn','女媧','Nǚwā','lang.lzh','Traditional Chinese (received text)','覽冥訓「往古之時」段','篇名与人名保留传世本繁体字形；字形异体只在说明中标注。','Chapter and personal names keep the received traditional-character forms; glyph variants are noted, not normalized away.','古籍原文属公共领域；数字版遵循 Chinese Text Project 条款。','2026-10-02T05:40:00Z'),
('storyver.chinese.nuwa_liezi_tangwen','列子·湯問','Lièzǐ · Tāngwèn','女媧氏','Nǚwā shì','lang.lzh','Traditional Chinese (received text)','湯問「天地亦物」段','保留“女媧氏”称谓；成书年代争议写入说明，不据此排序。','The designation “Nüwa-shi” is kept; the dating debate is noted and not used to order the witnesses.','古籍原文属公共领域；数字版遵循 Chinese Text Project 条款。','2026-10-02T05:40:00Z'),
('storyver.chinese.gonggong_huainanzi_tianwen','淮南子·天文訓','Huáinánzǐ · Tiānwén xùn','共工','Gònggōng','lang.lzh','Traditional Chinese (received text)','天文訓「昔者共工」段','本段独立于《覽冥訓》女娲段。','This passage is independent of the Lan Ming Nüwa passage.','古籍原文属公共领域；数字版遵循 Chinese Text Project 条款。','2026-10-02T05:40:00Z'),
('storyver.chinese.gonggong_liezi_tangwen','列子·湯問','Lièzǐ · Tāngwèn','共工氏','Gònggōng shì','lang.lzh','Traditional Chinese (received text)','湯問「其後共工氏」句','与女娲补天同在一段问答中，以“其後”接续。','Shares one dialogue passage with Nüwa''s repair and follows it with “afterwards”.','古籍原文属公共领域；数字版遵循 Chinese Text Project 条款。','2026-10-02T05:40:00Z'),
('storyver.hindu.churning_mbh_ce','महाभारत — आदिपर्वन्','Mahābhārata — Ādiparvan','अमृतमन्थन','amṛtamanthana','lang.san','Devanagari title; IAST e-text','Critical edition 1.15–1.17 (Āstīkaparvan)','精校本正文只是一种学术重建见证；写本校勘与附录另列队列。','The constituted critical text is one scholarly reconstruction; apparatus and appendices are queued separately.','GRETIL 文件条款适用；现代译本版权另计，不复制。','2026-10-02T05:40:00Z'),
('storyver.hindu.churning_bhagavata','भागवतपुराण','Bhāgavatapurāṇa','समुद्रमन्थन','samudramanthana','lang.san','Devanagari title; GRETIL transcription','Skandha 8, adhyāyas 5–9','活态经典：只做描述性概述，不裁定神学。','Living scripture: descriptive summaries only, with no theological adjudication.','GRETIL 文件条款适用；现代虔信译本不复制。','2026-10-02T05:40:00Z');

INSERT OR IGNORE INTO story_witness_comparisons(
    id,story_id,comparison_order,topic_zh,topic_en,comparison_scope,synthesis_policy,
    editorial_note_zh,editorial_note_en,created_at
) VALUES
('wcomp.nuwa.01_framing','story.chinese.nuwa_repairs_sky',1,'补天前的天地状况','How the need for repair is framed','DIVERGENT_ACCOUNT','KEEP_SEPARATE','《淮南子》写宇宙崩坏的场面，《列子》用“物有不足”的问答来说明。','The Huainanzi depicts a cosmic collapse; the Liezi explains the repair through a dialogue on deficient things.','2026-10-02T05:40:00Z'),
('wcomp.nuwa.02_stones_turtle','story.chinese.nuwa_repairs_sky',2,'五色石与鳌足','Five-colored stones and the turtle''s legs','SHARED_ELEMENT','KEEP_SEPARATE','两份见证都写炼石补天与断鳌足立四极。','Both witnesses have the stones and the turtle''s legs.','2026-10-02T05:40:00Z'),
('wcomp.nuwa.03_dragon_ash','story.chinese.nuwa_repairs_sky',3,'黑龙与芦灰','The black dragon and reed ash','ASYMMETRIC_WITNESS','KEEP_SEPARATE','只有《淮南子》写到；“未陈述”不是反证。','Only the Huainanzi has them; not stated is not counter-evidence.','2026-10-02T05:40:00Z'),
('wcomp.nuwa.04_gonggong','story.chinese.nuwa_repairs_sky',4,'共工事件的位置','Where Gonggong appears','DIVERGENT_ACCOUNT','NO_SYNTHESIS','两份见证都不把共工写成补天的起因；不合成后世因果版本。','Neither witness makes Gonggong the cause of the repair; no later causal version is synthesized.','2026-10-02T05:40:00Z'),
('wcomp.gonggong.01_pillar','story.chinese.gonggong_buzhou',1,'天柱折与地维绝','The broken pillar and snapped cords','SHARED_ELEMENT','KEEP_SEPARATE','两份见证共有撞山、折天柱与天倾西北；措辞略有差异。','Both share the collision, the broken pillar and the northwest tilt; the wording differs slightly.','2026-10-02T05:40:00Z'),
('wcomp.gonggong.02_placement','story.chinese.gonggong_buzhou',2,'叙事位置','Narrative placement','DIVERGENT_ACCOUNT','NO_SYNTHESIS','《天文训》独立成段，《列子》接在补天之后；见显式冲突档案。','“Tian Wen” stands alone, the Liezi follows the repair; see the explicit conflict record.','2026-10-02T05:40:00Z'),
('wcomp.churn.01_uprooting','story.hindu.samudra_manthana_texts',1,'谁拔起曼陀罗山','Who uproots Mount Mandara','DIVERGENT_ACCOUNT','KEEP_SEPARATE','两份见证对拔山者的叙述不同；均为中等置信度，待逐颂校对。','The witnesses differ on who uproots the mountain; both rows are medium confidence pending verse-level collation.','2026-10-02T05:40:00Z'),
('wcomp.churn.02_rod_rope','story.hindu.samudra_manthana_texts',2,'搅棒与搅绳','Churning rod and rope','SHARED_ELEMENT','KEEP_SEPARATE','两份见证都以曼陀罗山为搅棒、婆苏吉为搅绳。','Both witnesses use Mount Mandara as the rod and Vāsuki as the rope.','2026-10-02T05:40:00Z'),
('wcomp.churn.03_tortoise','story.hindu.samudra_manthana_texts',3,'托山的龟','The tortoise beneath the mountain','DIVERGENT_ACCOUNT','KEEP_SEPARATE','龟王阿库帕拉与毗湿奴的龟形化身分开建模；见显式冲突档案。','The tortoise king Akūpāra and Viṣṇu''s tortoise form are modeled separately; see the explicit conflict record.','2026-10-02T05:40:00Z'),
('wcomp.churn.04_poison','story.hindu.samudra_manthana_texts',4,'毒药与湿婆','The poison and Śiva','ASYMMETRIC_WITNESS','KEEP_SEPARATE','精校本当前定位未陈述，不等于所有写本都没有。','Not stated at the critical-edition locator does not mean that every manuscript lacks it.','2026-10-02T05:40:00Z'),
('wcomp.churn.05_emergent_items','story.hindu.samudra_manthana_texts',5,'涌现之物的逐项清单','Item-by-item list of emergent beings and treasures','EXPLICIT_UNKNOWN','NO_SYNTHESIS','本检查点尚未逐项对齐两份清单，不从任一版本补齐另一版本。','This checkpoint has not aligned the two lists item by item and does not fill one from the other.','2026-10-02T05:40:00Z'),
('wcomp.churn.06_dhanvantari','story.hindu.samudra_manthana_texts',6,'檀文陀利与甘露','Dhanvantari and the amṛta','SHARED_ELEMENT','KEEP_SEPARATE','两份见证都让檀文陀利捧着甘露出现。','Both witnesses have Dhanvantari emerge with the amṛta.','2026-10-02T05:40:00Z'),
('wcomp.churn.07_female_form_rahu','story.hindu.samudra_manthana_texts',7,'女身取回甘露与罗睺被斩','The female form, the amṛta and Rāhu','SHARED_ELEMENT','KEEP_SEPARATE','情节相近，但“摩希尼”专名实体只连接往世书见证。','The episodes are close, but the proper-name entity Mohinī is linked only to the Purāṇic witness.','2026-10-02T05:40:00Z');

INSERT OR IGNORE INTO story_witness_comparison_members(
    comparison_id,story_version_id,story_section_id,member_order,evidence_state,
    original_form,transliteration,source_location,anchor_claim_id,
    summary_zh,summary_en,difference_note_zh,difference_note_en,created_at
) VALUES
('wcomp.nuwa.01_framing','storyver.chinese.nuwa_huainanzi_lanming','storysec.v0300.nuwa.lanming.1',1,'ATTESTED','四極廢，九州裂','sìjí fèi, jiǔzhōu liè','覽冥訓「往古之時」段','claim.v0300.nuwa.lanming_collapse','描写四极崩坏、九州开裂与水火不息。','Depicts the failure of the four poles, the splitting of the provinces and unchecked fire and flood.','是叙事场景，不是哲学问答。','A narrative scene rather than a philosophical dialogue.','2026-10-02T05:40:00Z'),
('wcomp.nuwa.01_framing','storyver.chinese.nuwa_liezi_tangwen','storysec.v0300.nuwa.liezi.1',2,'ATTESTED','物有不足','wù yǒu bùzú','湯問「天地亦物」段','claim.v0300.nuwa.liezi_deficiency_frame','以天地也是物、物有不足来说明补天。','Explains the repair by treating heaven and earth as deficient things.','没有描写崩坏场面。','Does not depict a collapse scene.','2026-10-02T05:40:00Z'),
('wcomp.nuwa.02_stones_turtle','storyver.chinese.nuwa_huainanzi_lanming','storysec.v0300.nuwa.lanming.2',1,'ATTESTED','五色石；鼇足','wǔsè shí; áo zú','覽冥訓「往古之時」段','claim.v0300.nuwa.uses_stones','炼五色石补苍天，断鳌足立四极。','Refines five-colored stones to patch the sky and cuts the turtle''s legs to set up the four poles.','“鼇／鰲”等字形依版本而异。','Glyphs such as 鼇／鰲 vary by edition.','2026-10-02T05:40:00Z'),
('wcomp.nuwa.02_stones_turtle','storyver.chinese.nuwa_liezi_tangwen','storysec.v0300.nuwa.liezi.2',2,'ATTESTED','五色石；鰲之足','wǔsè shí; áo zhī zú','湯問「天地亦物」段','claim.v0300.nuwa.uses_stones','炼五色石补其缺，断鳌之足立四极。','Refines five-colored stones to fill the gap and cuts the turtle''s legs to set up the four poles.','补的对象写作“其闕”，承接问答语境。','The object repaired is “its gap”, following the dialogue context.','2026-10-02T05:40:00Z'),
('wcomp.nuwa.03_dragon_ash','storyver.chinese.nuwa_huainanzi_lanming','storysec.v0300.nuwa.lanming.3',1,'ATTESTED','黑龍；蘆灰','hēilóng; lú huī','覽冥訓「往古之時」段','claim.v0300.nuwa.kills_black_dragon','杀黑龙以济冀州，积芦灰以止洪水。','Kills the black dragon to relieve Jizhou and piles reed ash to stop the floods.','只在此见证出现。','Appears only in this witness.','2026-10-02T05:40:00Z'),
('wcomp.nuwa.03_dragon_ash','storyver.chinese.nuwa_liezi_tangwen',NULL,2,'NOT_STATED',NULL,NULL,'湯問「天地亦物」段',NULL,'当前段落没有写黑龙或芦灰。','The passage does not mention the black dragon or reed ash.','未陈述不是对《淮南子》的否定。','Not stated is not a denial of the Huainanzi.','2026-10-02T05:40:00Z'),
('wcomp.nuwa.04_gonggong','storyver.chinese.nuwa_huainanzi_lanming','storysec.v0300.nuwa.lanming.4',1,'NOT_STATED',NULL,NULL,'覽冥訓「往古之時」段',NULL,'女娲段落没有写共工。','The Nüwa passage does not mention Gonggong.','共工另见于同书《天文训》，两章不拼接。','Gonggong appears separately in “Tian Wen”; the chapters are not spliced.','2026-10-02T05:40:00Z'),
('wcomp.nuwa.04_gonggong','storyver.chinese.nuwa_liezi_tangwen','storysec.v0300.nuwa.liezi.3',2,'ATTESTED','其後','qí hòu','湯問「其後共工氏」句','claim.v0300.gonggong.liezi_after_nuwa','共工事件以“其后”接在补天之后。','The Gonggong episode follows the repair with “afterwards”.','是后续事件，不是补天的起因。','A subsequent event, not the cause of the repair.','2026-10-02T05:40:00Z'),
('wcomp.gonggong.01_pillar','storyver.chinese.gonggong_huainanzi_tianwen','storysec.v0300.gonggong.tianwen.2',1,'ATTESTED','天柱折，地維絕','tiānzhù zhé, dìwéi jué','天文訓「昔者共工」段','claim.v0300.gonggong.strikes_buzhou','撞山后天柱折断、地维断绝。','After the collision the pillar breaks and the cords snap.','结果写作积水与尘埃归东南。','The result has waters and dust gathering in the southeast.','2026-10-02T05:40:00Z'),
('wcomp.gonggong.01_pillar','storyver.chinese.gonggong_liezi_tangwen','storysec.v0300.gonggong.liezi.2',2,'ATTESTED','折天柱，絕地維','zhé tiānzhù, jué dìwéi','湯問「其後共工氏」句','claim.v0300.gonggong.strikes_buzhou','撞山后折断天柱、断绝地维。','The collision breaks the pillar and snaps the cords.','结果写作百川与积水归东南。','The result has all rivers and floodwaters flowing southeast.','2026-10-02T05:40:00Z'),
('wcomp.gonggong.02_placement','storyver.chinese.gonggong_huainanzi_tianwen','storysec.v0300.gonggong.tianwen.3',1,'ATTESTED','昔者共工','xīzhě Gònggōng','天文訓「昔者共工」段','claim.v0300.gonggong.tianwen_standalone','独立成段的天地形势起源。','A standalone etiology of cosmic orientation.','没有提到女娲。','Nüwa is not mentioned.','2026-10-02T05:40:00Z'),
('wcomp.gonggong.02_placement','storyver.chinese.gonggong_liezi_tangwen','storysec.v0300.gonggong.liezi.1',2,'ATTESTED','其後共工氏','qí hòu Gònggōng shì','湯問「其後共工氏」句','claim.v0300.gonggong.liezi_after_nuwa','接在女娲补天之后。','Follows Nüwa''s repair.','位置差异进入显式冲突档案。','The difference in placement is an explicit conflict record.','2026-10-02T05:40:00Z'),
('wcomp.churn.01_uprooting','storyver.hindu.churning_mbh_ce','storysec.v0300.churn.mbh.2',1,'ATTESTED','अनन्त','Ananta','Mahābhārata CE 1.16','claim.v0300.churn.mbh_ananta_uproots','巨蛇阿难陀拔起曼陀罗山。','The serpent Ananta uproots Mount Mandara.','中等置信度，待逐颂校对。','Medium confidence pending verse-level collation.','2026-10-02T05:40:00Z'),
('wcomp.churn.01_uprooting','storyver.hindu.churning_bhagavata','storysec.v0300.churn.bhp.1',2,'ATTESTED','देवासुराः','devāsurāḥ','Bhāgavatapurāṇa 8.6','claim.v0300.churn.bhp_devas_asuras_uproot','诸神与阿修罗合力拔山并运往大海。','Gods and asuras uproot the mountain together and carry it to the ocean.','毗湿奴协助运山，细节只作概述。','Viṣṇu helps with the transport; details are summarized only.','2026-10-02T05:40:00Z'),
('wcomp.churn.02_rod_rope','storyver.hindu.churning_mbh_ce','storysec.v0300.churn.mbh.2',1,'ATTESTED','मन्दर / वासुकि','Mandara / Vāsuki','Mahābhārata CE 1.16','claim.v0300.churn.mandara_rod','曼陀罗山为搅棒，婆苏吉为搅绳。','Mandara is the rod and Vāsuki the rope.','共享元素。','Shared element.','2026-10-02T05:40:00Z'),
('wcomp.churn.02_rod_rope','storyver.hindu.churning_bhagavata','storysec.v0300.churn.bhp.2',2,'ATTESTED','मन्दर / वासुकि','Mandara / Vāsuki','Bhāgavatapurāṇa 8.6–8.7','claim.v0300.churn.vasuki_rope','曼陀罗山为搅棒，婆苏吉为搅绳。','Mandara is the rod and Vāsuki the rope.','共享元素。','Shared element.','2026-10-02T05:40:00Z'),
('wcomp.churn.03_tortoise','storyver.hindu.churning_mbh_ce','storysec.v0300.churn.mbh.2',1,'ATTESTED','अकूपार','Akūpāra','Mahābhārata CE 1.16','claim.v0300.churn.akupara_supports','龟王阿库帕拉承托曼陀罗山。','The tortoise king Akūpāra bears Mount Mandara.','本见证没有说龟王是毗湿奴的化身。','This witness does not make the tortoise king a form of Viṣṇu.','2026-10-02T05:40:00Z'),
('wcomp.churn.03_tortoise','storyver.hindu.churning_bhagavata','storysec.v0300.churn.bhp.2',2,'ATTESTED','कूर्म','kūrma','Bhāgavatapurāṇa 8.7','claim.v0300.churn.kurma_supports','毗湿奴化作巨龟托起大山。','Viṣṇu takes the form of a giant tortoise to raise the mountain.','与阿库帕拉不做身份等同。','Not identified with Akūpāra.','2026-10-02T05:40:00Z'),
('wcomp.churn.04_poison','storyver.hindu.churning_mbh_ce','storysec.v0300.churn.mbh.5',1,'NOT_STATED',NULL,NULL,'Mahābhārata CE 1.15–1.17 (constituted text)',NULL,'精校本正文当前定位没有湿婆饮毒。','The constituted text at this locator does not have Śiva drinking the poison.','写本校勘与附录尚待核对。','The apparatus and appendices remain to be checked.','2026-10-02T05:40:00Z'),
('wcomp.churn.04_poison','storyver.hindu.churning_bhagavata','storysec.v0300.churn.bhp.3',2,'ATTESTED','हालाहल','hālāhala','Bhāgavatapurāṇa 8.7','claim.v0300.churn.shiva_drinks_poison','搅拌最先产生毒药，湿婆将其饮下。','The churning first produces a poison, which Śiva drinks.','本见证明确叙述。','Explicitly narrated in this witness.','2026-10-02T05:40:00Z'),
('wcomp.churn.05_emergent_items','storyver.hindu.churning_mbh_ce','storysec.v0300.churn.mbh.3',1,'UNMODELED',NULL,NULL,'Mahābhārata CE 1.16',NULL,'涌现之物的逐项清单尚未建模。','The item-by-item list of emergent beings and treasures is not yet modeled.','不从往世书补齐。','Not filled from the Purāṇa.','2026-10-02T05:40:00Z'),
('wcomp.churn.05_emergent_items','storyver.hindu.churning_bhagavata','storysec.v0300.churn.bhp.4',2,'UNMODELED',NULL,NULL,'Bhāgavatapurāṇa 8.8',NULL,'涌现之物的逐项清单尚未建模。','The item-by-item list of emergent beings and treasures is not yet modeled.','不从精校本补齐。','Not filled from the critical edition.','2026-10-02T05:40:00Z'),
('wcomp.churn.06_dhanvantari','storyver.hindu.churning_mbh_ce','storysec.v0300.churn.mbh.3',1,'ATTESTED','धन्वन्तरि','Dhanvantari','Mahābhārata CE 1.16','claim.v0300.churn.dhanvantari_carries_amrita','檀文陀利捧着甘露出现。','Dhanvantari emerges with the amṛta.','共享元素。','Shared element.','2026-10-02T05:40:00Z'),
('wcomp.churn.06_dhanvantari','storyver.hindu.churning_bhagavata','storysec.v0300.churn.bhp.4',2,'ATTESTED','धन्वन्तरि','Dhanvantari','Bhāgavatapurāṇa 8.8','claim.v0300.churn.dhanvantari_carries_amrita','檀文陀利捧着甘露出现。','Dhanvantari emerges with the amṛta.','共享元素。','Shared element.','2026-10-02T05:40:00Z'),
('wcomp.churn.07_female_form_rahu','storyver.hindu.churning_mbh_ce','storysec.v0300.churn.mbh.4',1,'ATTESTED','राहु','Rāhu','Mahābhārata CE 1.16–1.17','claim.v0300.churn.rahu_beheaded','那罗延以迷惑女身取回甘露，罗睺被神盘斩首。','Nārāyaṇa recovers the amṛta in a deluding female form; Rāhu is beheaded with the discus.','只描述女身，不连接摩希尼专名实体。','Describes a female form without linking the Mohinī entity.','2026-10-02T05:40:00Z'),
('wcomp.churn.07_female_form_rahu','storyver.hindu.churning_bhagavata','storysec.v0300.churn.bhp.5',2,'ATTESTED','मोहिनी / राहु','Mohinī / Rāhu','Bhāgavatapurāṇa 8.8–8.9','claim.v0300.churn.mohini_distributes','毗湿奴化身摩希尼分配甘露，罗睺被斩首。','Viṣṇu as Mohinī distributes the amṛta; Rāhu is beheaded.','专名实体只属于此见证。','The proper-name entity belongs to this witness only.','2026-10-02T05:40:00Z');

INSERT OR IGNORE INTO story_conflict_links(story_id,conflict_id,notes) VALUES
('story.hindu.samudra_manthana_texts','conflict.v0300.hindu.churning_tortoise_support','v0.30 witness comparison; Akūpāra and Kūrma are not equated.'),
('story.chinese.gonggong_buzhou','conflict.v0300.china.gonggong_placement','Standalone etiology versus sequel to Nüwa''s repair.'),
('story.chinese.nuwa_repairs_sky','conflict.v0300.china.gonggong_placement','The Liezi witness attaches Gonggong after the repair; no causal synthesis.');

INSERT OR IGNORE INTO reading_routes(
    id,title_zh,title_en,route_type,description_zh,description_en,evidence_policy,
    featured_order,created_at,updated_at
) VALUES
('route.textual_material_witness_layers','文本见证与物质见证分层阅读','Reading textual and material witnesses in layers','WITNESS','从同一故事的两种古典文本见证，读到同一主题的梵语文本与吴哥寺浮雕；每一步都保留自己的来源，不让文本替浮雕决定版本。','Move from two classical witnesses of one story to Sanskrit texts and the Angkor Wat relief on the same theme; every step keeps its own source, and no text decides the relief''s recension.','Each step keeps its own witness; textual witnesses never determine a material witness''s recension, and later retellings are not back-projected.',70,'2026-10-02T05:40:00Z','2026-10-02T05:40:00Z');

INSERT OR IGNORE INTO reading_route_steps(
    route_id,step_order,story_id,story_version_id,focus_entity_id,
    rationale_zh,rationale_en,transition_note
) VALUES
('route.textual_material_witness_layers',1,'story.chinese.nuwa_repairs_sky','storyver.chinese.nuwa_huainanzi_lanming','deity.chinese.nu_wa','先读《淮南子》中的宇宙崩坏与修补。','Start with cosmic collapse and repair in the Huainanzi.','同一故事的另一份见证。'),
('route.textual_material_witness_layers',2,'story.chinese.nuwa_repairs_sky','storyver.chinese.nuwa_liezi_tangwen','deity.chinese.nu_wa','比较《列子》的问答框架与缺失的黑龙、芦灰。','Compare the Liezi dialogue frame and the missing dragon and reed ash.','同一段问答继续写到共工。'),
('route.textual_material_witness_layers',3,'story.chinese.gonggong_buzhou','storyver.chinese.gonggong_liezi_tangwen','deity.chinese.gonggong','看共工事件如何以“其后”接续，而不是作为起因。','See how the Gonggong episode follows with “afterwards” rather than acting as a cause.','转入另一传统；路线不代表同源。'),
('route.textual_material_witness_layers',4,'story.hindu.samudra_manthana_texts','storyver.hindu.churning_mbh_ce','creature.hindu.akupara','读精校本中由龟王托山的版本。','Read the critical-edition version in which the tortoise king bears the mountain.','同一故事的往世书见证。'),
('route.textual_material_witness_layers',5,'story.hindu.samudra_manthana_texts','storyver.hindu.churning_bhagavata','deity.hindu.kurma','比较毗湿奴化龟与湿婆饮毒。','Compare Viṣṇu''s tortoise form and Śiva drinking the poison.','从文本见证转到物质见证。'),
('route.textual_material_witness_layers',6,'story.khmer.angkor_wat_churning_relief','storyver.khmer.angkor_churning_apsara','monument.khmer.angkor_wat_churning_relief','最后看吴哥寺浮雕：同一主题的高棉物质见证，不由文本决定其版本。','End with the Angkor Wat relief: a Khmer material witness of the theme whose recension is not decided by the texts.',NULL),
('route.artifact_circulation',5,'story.hindu.samudra_manthana_texts','storyver.hindu.churning_mbh_ce','artifact.hindu.amrita','甘露从大海涌现，被阿修罗夺走，再由迷惑女身取回。','The amṛta emerges from the ocean, is seized by the Dānavas and recovered through a deluding female form.','路线是编辑导航，不代表各传统神器同源。');

INSERT OR IGNORE INTO tradition_access_policies(
    id,entity_id,source_id,authority_name,community_context,access_level,
    permitted_scope,prohibited_scope,attribution_requirement,
    permission_contact_or_process,policy_basis,reviewed_at,notes
) VALUES
('policy.v0300.hindu.bhagavata_public','text.hindu.bhagavata_purana','source.india.bhagavatapurana.gretil','GRETIL public Sanskrit e-text','The Bhāgavata Purāṇa remains scripture in living devotional traditions, notably Vaiṣṇava communities.','PUBLIC_CONTEXT','Locators, metadata and independently written descriptive summaries of public scriptural passages.','No adjudication of theology, sectarian interpretation or ritual practice; no bulk reproduction of modern devotional translations.','Name the Purāṇa, skandha and adhyāya locator and the GRETIL e-text.','Consult named community or institutional authorities before adding ritual, commentarial or performance material.','Public scripture text plus WMS living-tradition methodology.','2026-10-02T05:40:00Z','Descriptive narrative summaries only.');

