    discovery_context,priority,status,attempts,last_error,next_action,created_at,updated_at
) VALUES
('queue.v0300.china.nuwa_later_causal_link','Later Chinese witnesses linking Gonggong''s collision to Nüwa''s repair','later chinese witnesses gonggong collision nuwa repair causal link','TEXT','civ.chinese_ancient','event.chinese.nuwa_repairs_sky','claim.v0300.nuwa.causal_link_boundary','source.china.liezi.tangwen.ctext','The two early witnesses do not make the collision the cause of the repair; later retellings that do must be registered as their own reception layer.',90,'DISCOVERED',0,NULL,'Register later witnesses such as the Tang-period supplement on the Three Sovereigns with exact locators and dates; never back-project the causal link into the Huainanzi or Liezi.','2026-10-02T05:40:00Z','2026-10-02T05:40:00Z'),
('queue.v0300.india.churning_apparatus','Mahābhārata critical apparatus and appendix passages for the churning','mahabharata critical apparatus appendix churning','TEXT','civ.hindu','event.hindu.samudra_manthana','claim.v0300.churn.mbh_poison_scope','source.india.bori_mahabharata','The poison episode is NOT_STATED in the constituted text at Ādiparvan 1.15–1.17; manuscript evidence has not been collated.',92,'DISCOVERED',0,NULL,'Consult the BORI apparatus and appendix volumes for Ādiparvan 1.15–1.17 and record which manuscript groups carry the poison episode; never treat NOT_STATED as absence from every manuscript.','2026-10-02T05:40:00Z','2026-10-02T05:40:00Z'),
('queue.v0300.india.churning_further_witnesses','Further dated textual witnesses of the churning of the ocean','further dated textual witnesses churning ocean','TEXT','civ.hindu','event.hindu.samudra_manthana','claim.v0300.churn.bhp_witness','source.india.gretil','Two witnesses are registered; other epic and Purāṇic accounts remain unaligned.',88,'DISCOVERED',0,NULL,'Register further accounts (for example the Rāmāyaṇa Bālakāṇḍa and Viṣṇu Purāṇa) from authoritative editions with exact locators; keep each witness separate.','2026-10-02T05:40:00Z','2026-10-02T05:40:00Z'),
('queue.v0300.india.ananta_entity','Ananta (Śeṣa) entity and witness-scoped roles','ananta sesa entity witness scoped roles','CREATURE','civ.hindu','place.hindu.mandara','claim.v0300.churn.mbh_ananta_uproots','source.india.mahabharata.adiparvan.gretil','Ananta appears as a literal in the critical-edition churning claim but has no entity yet.',80,'DISCOVERED',0,NULL,'Create the Ananta entity only with source-backed names and roles; do not merge with other serpent figures by name alone.','2026-10-02T05:40:00Z','2026-10-02T05:40:00Z');

